    const rr = R - ring * 12;
    const mat = ring < 2 ? ICE : ACID;
    for (let ang = 0.05; ang < Math.PI - 0.05; ang += 0.004) {
      const x = cx + Math.cos(ang) * rr;
      const y = cy - Math.sin(ang) * rr * 0.78;
      set(a, x|0, y|0, mat);
    }
