  // Scalloped bottom rim of the bell
  for (let ang = 0; ang <= Math.PI; ang += 0.02) {
    const x = cx + Math.cos(ang) * R;
    const y = cy + 2 + Math.sin(ang * 9) * 8;
    set(a, x|0, y|0, ICE);
    set(a, x|0, (y + 1)|0, ICE);
  }
  // Bright bioluminescent core inside the bell (bloom → white-hot heart)
  disk(a, cx, cy - 44, 30, ICE);
  disk(a, cx, cy - 44, 12, ACID);

  // Long trailing tentacles — the main gesture, flowing + thinning downward
  const nT = 11;
  for (let i = 0; i < nT; i++) {
    const f = i / (nT - 1) - 0.5;                 // -0.5..0.5 across the bell
    const bx = cx + f * R * 1.1;
    const len = 330 + Math.cos(f * 3) * 40;
    const phase = i * 0.8;
    const amp = 16 + Math.abs(f) * 20;
    let px = bx, py = cy + 6;
    for (let s = 1; s <= 120; s++) {
      const y = cy + 6 + (s / 120) * len;
      const drift = Math.sin(y * 0.02 + phase) * amp * (s / 120);
      const x = bx + drift + f * 30 * (s / 120);
      const mat = (i % 3 === 0) ? ACID : ICE;      // a few green threads among the cyan
      line(a, px|0, py|0, x|0, y|0, mat, 1);
      px = x; py = y;
    }
  }
  // Thicker oral arms near the center
  for (let i = -1; i <= 1; i++) {
    let px = cx + i * 22, py = cy;
    for (let s = 1; s <= 90; s++) {
      const y = cy + (s / 90) * 230;
      const x = cx + i * 22 + Math.sin(y * 0.03 + i) * 24 * (s / 90);
      line(a, px|0, py|0, x|0, y|0, ICE, 2);
      px = x; py = y;
    }
  }

  // --- Bioluminescent plankton scattered through the void (sparse, so it stays clean) ---
  for (let i = 0; i < 260; i++) {
    const x = h2(i * 1.3, 7.1) * W;
    const y = h2(i * 2.7, 3.3) * H;
    if (h2(i, i * 0.5) > 0.62) set(a, x|0, y|0, (i % 4 === 0) ? ACID : ICE);
  }
  // A diagonal drift of brighter motes sweeping across the empty right side — leads the eye
  for (let i = 0; i < 60; i++) {
    const t = i / 60;
    const x = 700 + t * 440 + Math.sin(t * 10) * 20;
    const y = 380 - t * 300 + Math.cos(t * 8) * 16;
    set(a, x|0, y|0, ACID);
    if (i % 3 === 0) disk(a, x|0, y|0, 1, ICE);
