  disk(a, hx + 10, hy - 40, 6, GUNPOWDER);
  set(a, hx + 7, hy - 43, ICE);

  // Rim light on the head contour facing the lure (upper-right arc)
  for (let ang = -0.7; ang < 1.1; ang += 0.02) {
    const x = hx + Math.cos(ang) * 118;
    const y = hy - Math.sin(ang) * 118;
    set(a, x|0, y|0, ICE);
  }

  // ===== The lure — the sun of the abyss, on the upper-right thirds intersection =====
  const lurX = 760, lurY = 205;
  // Illicium rod: quadratic arc from forehead up to the lure
  const P0 = [hx + 40, hy - 110], Pc = [hx + 230, hy - 250], P1 = [lurX, lurY + 20];
  let rpx = P0[0], rpy = P0[1];
  for (let s = 1; s <= 40; s++) {
    const t = s / 40, u = 1 - t;
    const x = u * u * P0[0] + 2 * u * t * Pc[0] + t * t * P1[0];
    const y = u * u * P0[1] + 2 * u * t * Pc[1] + t * t * P1[1];
    line(a, rpx|0, rpy|0, x|0, y|0, GUNPOWDER, 2);
    rpx = x; rpy = y;
  }
  // The glowing bulb — layered for an intense white-hot bloom core
  disk(a, lurX, lurY, 16, ICE);    // cold halo
  disk(a, lurX, lurY, 11, ACID);   // fluorescent flesh
  disk(a, lurX, lurY, 4, SALT);    // white-hot center

  // God-rays: faint radiating motes lit by the lure
  for (let r = 0; r < 22; r++) {
    const ang = (r / 22) * Math.PI * 2;
    const len = 40 + h2(r, 1.3) * 120;
    for (let d = 22; d < len; d += 6) {
      const x = lurX + Math.cos(ang) * d;
      const y = lurY + Math.sin(ang) * d;
      if (h2(r * d, d) > 0.4) set(a, x|0, y|0, ACID);
    }
  }
}

(a) => {
  // 1) 무한 어둠 위 촘촘한 별밭. 배경(0)은 그대로 두고 별만 h2로 흩뿌린다.
  //    아주 밝은 별은 ICE(시안 발광)라 bloom으로 반짝, 잔별은 SALT(흰).
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const r = h2(x * 1.7, y * 1.3);
      if (r > 0.9975) set(a, x, y, ICE);       // 소수의 밝은 시안 별 (주연급 반짝임)
      else if (r > 0.9915) set(a, x, y, SALT);  // 촘촘한 흰 잔별
    }
  }

  // 2) 성운 가스 구름. 초점은 우측 삼분할(cx,cy), 왼쪽은 여백으로 비운다.
  //    fbm 마스크 + 중심 거리 falloff로 뭉게뭉게, 밀도 충분히 높게.
  const cx = 770, cy = 285;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const dx = (x - cx) / 430, dy = (y - cy) / 300;
      const d = Math.sqrt(dx * dx + dy * dy);   // 0(중심)~1+(가장자리)
      const n = fbm(x * 0.0062 + 11, y * 0.0062);
      const density = n * 1.25 - d * 1.05;      // 중심으로 갈수록 진함

      if (density > 0.82) set(a, x, y, FIRE);         // 화이트핫 코어 (극적 발광)
      else if (density > 0.50) set(a, x, y, ACID);    // 형광초록 본체 가스
      else if (density > 0.24) {                       // 바깥 wisp: 시안/초록 교차
        const n2 = fbm(x * 0.011 - 5, y * 0.011 + 7);
        set(a, x, y, n2 > 0.52 ? ICE : ACID);
      } else if (density > 0.12) {                      // 옅은 외곽 헤일로
        if (fbm(x * 0.02 + 3, y * 0.02) > 0.6) set(a, x, y, STEAM);
      }
    }
  }

  // 3) 코어 한가운데 작은 화이트핫 점 하나 더 — 시선 앵커 & 렌즈플레어 유발.
  disk(a, cx, cy, 4, FIRE);
}

(a) => {
  // 1) 별밭 먼저 — 화면 전체에 깊이감. 밝은 시안별 + 흰 잔별.
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const r = h2(x * 1.9, y * 1.1);
      if (r > 0.9978) set(a, x, y, ICE);
      else if (r > 0.9945) set(a, x, y, SALT);
    }
  }

  // 2) 기울어진 나선은하. 중심은 좌측 삼분할, 세로를 눌러 tilt한 원반처럼.
  const cx = 465, cy = 300;
  const twist = 0.021;        // 로그나선 꼬임
  const rMax = 350;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const dx = x - cx, dy = (y - cy) * 1.55;   // 세로 압축 = 원반을 비스듬히 본 각
      const rad = Math.sqrt(dx * dx + dy * dy);
      if (rad > rMax) continue;

      const ang = Math.atan2(dy, dx);
      const s = Math.sin(2 * ang - rad * twist);  // 팔 2개짜리 나선
      const armMask = Math.pow(Math.max(0, s), 1.6);
      const n = fbm(x * 0.02, y * 0.02);
      const falloff = 1 - rad / rMax;
      const val = armMask * falloff * 1.35 + n * 0.28 * falloff;

      // 중심 팽대부: 화이트핫 코어 + 형광 링
      if (rad < 40) { set(a, x, y, rad < 22 ? FIRE : ACID); continue; }

      if (val > 0.48) set(a, x, y, ACID);              // 나선팔 본체 (형광초록 발광)
      else if (val > 0.30) set(a, x, y, ICE);          // 팔 가장자리 시안
      else if (val > 0.17 && n > 0.55) set(a, x, y, ICE); // 흩날리는 성단 알갱이
    }
  }
}

(a) => {
