}

(a) => {
  // ---- Cavern void: deep dark sky warming to a faint charcoal glow at the horizon ----
  vgrad(a, 0, 340, EMPTY, GUNPOWDER);
  const HORIZON = 320;

  // ---- Back cliff wall (dark silhouette) with a notch the lavafall pours through ----
  for (let x = 0; x < W; x++) {
    const edge = 150 + fbm(x * 0.02, 3.0) * 70 + Math.sin(x * 0.03) * 18; // jagged skyline
    const notch = (x > 820 && x < 900) ? 260 : 0;    // deep gap for the fall
    const top = Math.max(edge, notch);
    for (let y = 0; y < top && y < HORIZON; y++) {
      const n = fbm(x * 0.03, y * 0.03);
      set(a, x, y, n > 0.66 ? STONE : GUNPOWDER);
    }
  }

  // ---- The molten lake: cracked crust, cooling toward the back, hot molten at the front ----
  for (let y = HORIZON; y < H; y++) {
    const depth = (y - HORIZON) / (H - HORIZON);     // 0 back -> 1 front
    for (let x = 0; x < W; x++) {
      const plate = fbm(x * 0.02, y * 0.05 + 10);    // floating dark plates
      const crustThresh = 0.5 - depth * 0.28;        // back = more crust, front = more molten
      let m;
      if (plate > crustThresh) {
        m = (plate > 0.8) ? STONE : GUNPOWDER;       // cooled skin
      } else {
        m = LAVA;                                     // glowing veins between plates
        if (plate < crustThresh - 0.12) m = FIRE;     // hottest crack cores
      }
      set(a, x, y, m);
    }
  }

  // ---- The lavafall: bright molten column pouring through the cliff notch ----
  for (let y = 60; y < HORIZON + 8; y++) {
    const cx = 860 + Math.sin(y * 0.08) * 4;         // slight wobble as it falls
    const w = 10 + (y - 60) * 0.05;                  // widens on the way down
    rect(a, (cx - w) | 0, y, (cx + w) | 0, y, LAVA);
    rect(a, (cx - w * 0.4) | 0, y, (cx + w * 0.4) | 0, y, FIRE); // white-hot core
  }
  disk(a, 860, HORIZON + 6, 40, LAVA);               // splash pool at the strike point
  disk(a, 860, HORIZON + 6, 20, FIRE);

  // ---- Smoke plumes billowing up from the impact, drifting with the draft ----
  for (let i = 0; i < 900; i++) {
    const baseX = 860 + (h2(i, 5.5) - 0.5) * 120;
    const t = h2(i, 7.7);
    const x = (baseX + (h2(i, 9.9) - 0.5) * 90 - t * 30) | 0;
    const y = (HORIZON - t * 300) | 0;
    if (y > 0 && h2(i, 3.3) > 0.55) set(a, x, y, SMOKE);
  }

  // ---- Embers: sparks lofting off the molten surface ----
  for (let i = 0; i < 300; i++) {
    const x = (h2(i, 1.1) * W) | 0;
    const y = (HORIZON - h2(i, 6.6) * 220) | 0;
    if (y > 0 && h2(i, 4.4) > 0.6) set(a, x, y, FIRE);
  }
}

(a) => {
  // 어두운 밤 배경(빈=근검정)에 빛나는 시안 얼음 첨탑들이 얼어붙은 호수에서 솟는다.
  // 구도: 수평선을 2/3 지점(호수)으로 낮추고, 중앙 우측에 최고봉 초점 + 좌우로 리듬 있게 배치.
  const horizon = 402;

  // 호수: 위(수면 근처)는 어둡고 깊이로 갈수록 진한 파랑 — 디더 그라데이션으로 깊이감.
  vgrad(a, horizon, H - 1, EMPTY, WATER);

  // 하늘 얼음 먼지(별처럼 반짝) — 상단에만 성기게. bloom으로 시안 스파클.
  for (let i = 0; i < 520; i++) {
    const x = Math.round(h2(i, 3.1) * W);
    const y = Math.round(h2(i, 7.7) * horizon * 0.9);
    if (h2(x, y) > 0.6) set(a, x, y, ICE);
  }

  // 결정 첨탑: 꼭대기(apexY)에서 밑변(호수변)까지 좁아지는 삼각 크리스탈 + 물 반사.
  const spire = (ax, apexY, halfW) => {
    const baseY = horizon;
    for (let yy = apexY; yy <= baseY; yy++) {
      const t = (yy - apexY) / (baseY - apexY);
      const hw = Math.max(1, halfW * t);
      line(a, ax - hw, yy, ax + hw, yy, ICE, 1); // 몸체
    }
    disk(a, ax, apexY, 2, ICE); // 뾰족한 꼭짓점의 화이트핫 스파크

    // 수면 반사: 호수로 미러링하되 잔물결로 조각내 물처럼 보이게.
    const h = baseY - apexY;
    for (let yy = 0; yy < h * 0.68; yy++) {
      const srcY = baseY - yy;
      const t = (srcY - apexY) / (baseY - apexY);
      const hw = Math.max(1, halfW * t) * 0.88;
      const ry = horizon + yy;
      if (ry >= H) break;
      if (h2(ax, ry * 2.7) < 0.5) continue; // 물결로 행 스킵
      line(a, ax - hw, ry, ax + hw, ry, ICE, 1);
    }
  };

  // 원경(작고 낮음) → 근경(크고 높음) 순서로 원근.
  spire(250, 322, 15);
  spire(960, 300, 17);
  spire(350, 252, 23);
  spire(858, 236, 25);
  spire(470, 150, 36);
  spire(742, 130, 40);
  spire(610, 68, 48); // 중앙 우측 최고봉 = 초점

  // 첨탑 밑동을 잇는 얇은 서리 능선(호수변) — 살짝 빛나 지평을 규정.
  for (let x = 200; x < 1000; x++) {
    if (h2(x, 99) > 0.7) set(a, x, horizon - Math.round(h2(x, 5) * 2), ICE);
  }
};

(a) => {
  // 완벽한 6방 대칭 눈결정 만다라. 어두운 배경 정중앙에 화이트핫 코어가 시안으로 폭발.
  const cx = 600, cy = 290;

  // 얼음 먼지 성단 — 성기게 뿌려 깊은 우주적 배경.
  for (let i = 0; i < 700; i++) {
