    rect(a, cx - sw, cy, cx + sw, base, WOOD);      // 어두운 줄기
  };

  // 구도: 좌측 삼분할의 히어로 군락, 오른쪽으로 작아지며 후퇴.
  shroom(300, 470, 90, ICE);   // 히어로, 큰 시안
  shroom(230, 500, 46, ICE);   // 형제
  shroom(360, 520, 34, ACID);  // 작은 초록 악센트
  shroom(720, 430, 40, ICE);   // 중경
  shroom(840, 450, 26, ACID);
  shroom(980, 405, 20, ICE);   // 원경
  shroom(1080, 395, 14, ACID);

  // 히어로 갓에서 피어오르는 옅은 포자 궤적 — 시선을 위로 끄는 리딩 라인.
  for (let i = 0; i < 40; i++) {
    const t = i / 40;
    const x = 300 + Math.sin(i * 0.6) * 30 + t * 40;
    const y = 380 - t * 260;
    if (h2(i, 71) > 0.35) set(a, x | 0, y | 0, ICE);
  }
}

(a) => {
  // 천장에서 늘어진 발광 넝쿨 — 어두운 줄기 끝에 차가운 빛 방울이 맺힌다. Scene1과 반대 방향(하강) 구도.
  vgrad(a, 0, H, GUNPOWDER, EMPTY); // 천장 쪽 옅은 빛, 아래는 공허

  // 배경 심연: 성긴 차가운 포자 먼지.
  for (let i = 0; i < 180; i++) {
    const x = (h2(i, 5) * W) | 0;
    const y = (h2(i, 13) * H) | 0;
    if (h2(i, 23) > 0.8) set(a, x, y, h2(i, 2) > 0.5 ? ICE : ACID);
  }

  // 넝쿨 헬퍼: 천장에서 흔들리며 내려오는 어두운 줄기 + 발광 방울들.
  const vine = (x0, len, sway, bulb) => {
    let px = x0, py = 0;
    for (let s = 0; s < len; s++) {
      const x = x0 + Math.sin(s * 0.05) * sway; // 완만한 컬
      const y = s;
      line(a, px | 0, py | 0, x | 0, y | 0, WOOD, 3); // 어두운 넝쿨 본체
      px = x; py = y;
      if (s % 46 === 0 && s > 30) disk(a, x | 0, y | 0, 5, bulb); // 중간 방울
    }
    disk(a, px | 0, py | 0, 9, bulb); // 끝 방울(가장 강한 글로우)
    disk(a, px | 0, py | 0, 4, ICE);  // 화이트핫 코어
  };

  // 상단을 가로지르는 리듬 + 중앙 좌측(황금비 근처)에 가장 긴 히어로 쌍.
  vine(120, 180, 24, ACID);
  vine(220, 300, 30, ICE);
  vine(300, 150, 18, ACID);
  vine(470, 430, 40, ICE);   // 히어로 — 최장, 좌중앙
  vine(540, 360, 34, ICE);
  vine(610, 470, 46, ACID);  // 히어로 페어
  vine(760, 220, 26, ICE);
  vine(880, 330, 36, ACID);
  vine(980, 200, 22, ICE);
  vine(1080, 280, 30, ACID);

  // 바닥 웅덩이: 빛이 고이는 옅은 발광 미스트.
  for (let i = 0; i < 300; i++) {
    const x = (h2(i, 31) * W) | 0;
    const y = (H - 6 - h2(i, 37) * 46) | 0;
    if (h2(i, 43) > 0.62) set(a, x, y, h2(i, 9) > 0.7 ? ICE : ACID);
  }
}
